import {CITIES} from './demo.js';
﻿import {user,pair,canChat,discover,notifications,visibleEvents} from './domain.js';
import {EVENT_TYPES} from './data.js';

export const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={discover:'M4 5h12v14H4z M8 2h12v14',harmonies:'M4 5h16v11H9l-5 4V5z M8 9h8 M8 12h5',explore:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M15 9l-2 4-4 2 2-4z',profile:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',arrow:'M5 12h14 M13 6l6 6-6 6',close:'M6 6l12 12 M18 6L6 18',star:'M12 2l2.7 6.8L22 12l-7.3 3.2L12 22l-2.7-6.8L2 12l7.3-3.2z',save:'M6 3h12v18l-6-4-6 4z',switch:'M4 7h16 M16 3l4 4-4 4 M20 17H4 M8 13l-4 4 4 4',back:'M19 12H5 M11 6l-6 6 6 6',bell:'M6 16h12l-2-3V8a4 4 0 0 0-8 0v5z M10 20h4'};
export const icon = (name)=>`<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
export const avatar = u=>`<span class="avatar" style="--avatar:${esc(u.color||'#8c7853')}">${esc(u.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span>`;
export const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const brand=()=>`<span class="brandmark">H</span><span>harmonia<span class="gold">.</span></span>`;
const date=e=>new Date(e.date+'T12:00:00').toLocaleDateString('nl-BE',{day:'numeric',month:'short'});
const tags=arr=>arr.map(i=>`<span class="chip">${esc(i)}</span>`).join('');

export function loginView({state,accountRole,accountSearch}) {
  const counts={student:state.users.filter(u=>u.role==='student').length,business:state.users.filter(u=>u.role==='business').length,admin:1};
  const list=state.users.filter(u=>u.active&&u.role===accountRole&&`${u.name} ${u.study||u.category||''} ${u.city||''}`.toLowerCase().includes(accountSearch.toLowerCase()));
  return `<main class="login"><div class="brand">${brand()}</div><div class="login-heading"><span class="eyebrow">JOUW SPEELRUIMTE · DRIE STEDEN</span><h1>Find your<br><em>harmony.</em></h1><p>Nieuwe gezichten. Jouw tempo.</p></div><section class="account-panel"><div class="section-heading"><h2>Wie ben je vandaag?</h2><span class="demo-badge">TESTACCOUNTS</span></div><div class="segmented" role="group" aria-label="Accounttype">${[['student','Studenten'],['business','Bedrijven'],['admin','Admin']].map(([id,label])=>button(`${label} <span>${counts[id]}</span>`,'account-role',id,accountRole===id?'active':'')).join('')}</div><label class="search-label">Zoek een account<input id="account-search" value="${esc(accountSearch)}" placeholder="Naam, stad, studie of bedrijf…" autocomplete="off"></label><div class="account-grid">${list.map(u=>{const n=u.role==='student'?notifications(state,u.id):{total:0};return `<button class="account" data-action="login" data-id="${u.id}">${avatar(u)}<span><strong>${esc(u.name)}</strong><small>${u.role==='student'?esc(u.study)+' · '+esc(u.city):u.role==='admin'?'Overzicht, beheer & resets':esc(u.category)+' · '+esc(u.city)}</small></span>${n.total?`<span class="count-badge">${n.total}</span>`:icon('arrow')}</button>`;}).join('')||'<p class="empty">Geen accounts gevonden. Probeer een andere naam.</p>'}</div><p class="small muted">Fictieve accounts · wissel vrij · alles wordt lokaal bewaard</p></section></main>`;
}
export function studentShell(c,body){
  const {state,u,page}=c,n=notifications(state,u.id);
  return `<div class="desktop-caption"><span class="eyebrow">HARMONIA / PLAYGROUND</span><h2>Een nieuwe klik.<br>Een nieuw verhaal.</h2><p>Find your harmony.</p><span class="small">Gent · Leuven · Antwerpen<br>120 studenten · 36 bedrijven</span></div><div class="phone-shell"><header class="phone-header"><a class="brand" href="#">${brand()}</a><button class="account-switch" data-action="logout" aria-label="Wissel testaccount">${avatar(u)}${icon('switch')}</button></header><main class="phone-main ${page==='harmonies'&&c.chat?'chat-open':''}" id="main-content">${body}</main><nav class="bottom-nav" aria-label="Hoofdnavigatie">${[['discover','Discover'],['harmonies','Harmonies'],['explore','Explore'],['profile','Profiel']].map(([id,label])=>`<button class="nav-item ${page===id?'selected':''}" ${page===id?'aria-current="page"':''} data-action="nav" data-id="${id}" aria-label="${label}${id==='harmonies'&&n.total?', '+n.total+' nieuw':''}"><span class="nav-icon">${icon(id)}${id==='harmonies'&&n.total?`<span class="count-badge">${n.total>99?'99+':n.total}</span>`:''}</span><span>${label}</span></button>`).join('')}</nav></div>${c.modal}`;
}
export function discoverPage(c){const {state,u,filter,region}=c,list=discover(state,u.id,filter,region),p=list[0],n=notifications(state,u.id);
 return `<div class="page-heading"><div><span class="eyebrow">${esc(region||'DRIE STEDEN')}, JOUW SPEELVELD</span><h1>Find your <em>harmony.</em></h1></div></div>${n.total?`<button class="notification-banner" data-action="nav" data-id="harmonies">${icon('bell')}<span><strong>${n.matches?`${n.matches} nieuwe ${n.matches===1?'Harmony':'Harmonies'}`:'Nieuwe berichten'}</strong><small>${n.messages?`${n.messages} ongelezen ${n.messages===1?'bericht':'berichten'}`:'Iemand wil jou leren kennen'}</small></span>${icon('arrow')}</button>`:''}<div class="discover-region"><label>Ontdek studenten in<select id="region"><option value="">Alle steden</option>${CITIES.map(city=>`<option ${region===city?'selected':''}>${city}</option>`).join('')}</select></label></div><div class="feed-toolbar"><span><i class="location-dot"></i> ${esc(region||'Alle steden')} <small>${list.length} te ontdekken</small></span><label class="filter"><span class="sr-only">Interesse</span><select id="interest"><option value="">Alle interesses</option>${[...new Set(state.users.filter(x=>x.role==='student').flatMap(x=>x.interests))].sort().map(i=>`<option ${filter===i?'selected':''}>${esc(i)}</option>`).join('')}</select></label></div>${p?`<div class="card-deck"><article class="swipe-card" tabindex="0" aria-label="Profiel van ${esc(p.name)}" data-profile="${p.id}"><div class="profile-art" style="--avatar:${p.color}"><div class="art-grain"></div><span class="verified">✓ ${esc(p.school)}</span><span class="swipe-stamp yes">LET'S CONNECT</span><span class="swipe-stamp no">VOLGENDE</span><span class="profile-monogram">${esc(p.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><div class="art-caption"><span>${esc(p.city)} · STUDENT</span><h2>${esc(p.name.split(' ')[0])}<span>, ${p.age}</span></h2><p>${esc(p.study)}</p></div><span class="art-spark">✦</span></div><div class="profile-content"><div class="intent">${icon('star')} ${esc(p.intent)}</div><p>${esc(p.bio)}</p><div class="chips">${p.interests.map(i=>`<span class="chip ${u.interests.includes(i)?'shared':''}">${u.interests.includes(i)?'✦ ':''}${esc(i)}</span>`).join('')}</div><div class="card-bottom"><span>${esc(p.languages)}</span>${button('Melden','report',p.id,'text-button')}${button('Blokkeren','block',p.id,'text-button')}</div></div></article></div><div class="swipe-controls"><button class="swipe-button pass" data-action="pass" data-id="${p.id}" aria-label="Swipe naar links">${icon('close')}</button><p>Een swipe.<br><strong>Een nieuw begin.</strong></p><button class="swipe-button like" data-action="like" data-id="${p.id}" aria-label="Swipe naar rechts">${icon('star')}</button></div><p class="gesture-hint">Sleep naar links of rechts · of gebruik ← →</p>`:`<div class="empty"><span>✦</span><h2>Helemaal bij.</h2><p>${filter?'Probeer een andere interesse.':'Wissel van account of reset de swipes in de admin om opnieuw te spelen.'}</p>${button('Naar je Harmonies','nav','harmonies','primary')}</div>`}`;
}
export function harmonyPage(c){const {state,u,chat}=c;const matches=state.matches.filter(m=>m.members.includes(u.id)&&canChat(state,u.id,m.members.find(x=>x!==u.id))).slice().reverse();const p=chat?user(state,chat):null;
 if(p&&canChat(state,u.id,p.id))return `<div class="conversation"><header class="conversation-head">${button(icon('back')+'<span class="sr-only">Terug naar Harmonies</span>','back-chats','','icon-button')}${avatar(p)}<div><strong>${esc(p.name)}</strong><small>Jullie hebben een Harmony</small></div>${button('Blokkeer','block',p.id,'text-button')}</header><div class="messages"><div class="chat-intro">✦ Het begin van iets leuks.<br><span>Zeg hallo, vind jullie klik.</span></div>${state.messages.filter(m=>pair(m.from,m.to)===pair(u.id,p.id)).map(m=>{const ev=m.eventId?state.events.find(e=>e.id===m.eventId):null;return `<div class="bubble ${m.from===u.id?'mine':''}">${m.eventId?(ev?`<div class="shared-event"><span class="eyebrow">SAMEN IETS DOEN?</span><strong>${esc(ev.title)}</strong><small>${date(ev)} · ${esc(ev.time)} · ${esc(user(state,ev.owner)?.name)}</small>${visibleEvents(state).some(x=>x.id===ev.id)?button('Bekijk activiteit ↗','event-detail',ev.id,'event-link'):'<small>Niet meer beschikbaar</small>'}</div>`:'<p>Deze activiteit is verwijderd.</p>'):esc(m.text)}<time>${new Date(m.at).toLocaleTimeString('nl-BE',{hour:'2-digit',minute:'2-digit'})}</time></div>`;}).join('')}</div><form id="message-form" class="message-form"><input name="text" aria-label="Bericht" placeholder="Zeg eens hallo…" required maxlength="2000" autocomplete="off"><button class="primary" aria-label="Verstuur bericht">${icon('arrow')}</button></form><button class="chat-share" data-action="choose-event">${icon('explore')} Deel een activiteit</button></div>`;
 return `<div class="page-heading"><span class="eyebrow">JULLIE HEBBEN EEN KLIK</span><h1>Jouw <em>Harmonies.</em></h1><p>${matches.length} ${matches.length===1?'connectie':'connecties'} · zoveel mogelijkheden</p></div>${matches.length?`<div class="harmony-list">${matches.map(m=>{const other=user(state,m.members.find(x=>x!==u.id)),fresh=!(m.seenBy||[]).includes(u.id),unread=state.messages.filter(x=>x.from===other.id&&x.to===u.id&&!(x.readBy||[]).includes(u.id)).length,last=state.messages.filter(x=>pair(x.from,x.to)===m.id).at(-1);return `<button class="chat-person" data-action="chat" data-id="${other.id}">${avatar(other)}<span><strong>${esc(other.name)} ${fresh?'<b class="new-label">NIEUW</b>':''}</strong><small>${last?.eventId?'◎ Een activiteit gedeeld':esc(last?.text||'Een nieuwe klik. Zeg eens hallo!')}</small></span>${unread?`<span class="count-badge">${unread}</span>`:icon('arrow')}</button>`;}).join('')}</div>`:`<div class="empty"><span>✦</span><h2>Wie wordt jouw eerste?</h2><p>Swipe naar rechts. Als jullie allebei een klik voelen, verschijnt je Harmony hier.</p>${button('Ontdek studenten','nav','discover','primary')}</div>`}`;
}
export function eventCard(state,u,e){const saved=state.saved.some(x=>x.user===u.id&&x.event===e.id);return `<article class="event-card"><button class="event-art type-${e.category.toLowerCase()}" data-action="event-detail" data-id="${e.id}" aria-label="Bekijk ${esc(e.title)}"><span class="event-category">${esc(e.category)}</span><span class="event-letter">${esc(e.category.slice(0,1))}<i>✦</i></span><span class="event-date">${date(e)}</span></button><div class="event-body"><span class="eyebrow">${esc(user(state,e.owner)?.name)}</span><h2>${esc(e.title)}</h2><p>${esc(e.city)} · ${esc(e.time)} · ${esc(e.price)}</p><div class="event-actions">${button(saved?'✓ Bewaard':'＋ Bewaren','save-event',e.id,saved?'quiet is-saved':'quiet')}${button('Samen gaan ↗','share-event',e.id,'text-button')}</div></div></article>`;}
export function explorePage(c){const {state,u,eventFilter,savedOnly}=c,list=visibleEvents(state,eventFilter,savedOnly?u.id:'');return `<div class="page-heading"><span class="eyebrow">DE STAD IS VAN JULLIE</span><h1>Ga samen <em>op pad.</em></h1><p>Alle activiteiten, voor alle studenten.</p></div><div class="category-filters" role="group" aria-label="Soort evenement">${['',...EVENT_TYPES].map(t=>button(t||'Alles','event-filter',t,eventFilter===t?'filter-chip active':'filter-chip')).join('')}</div><div class="feed-toolbar"><span>${list.length} ${list.length===1?'activiteit':'activiteiten'}</span><button class="saved-toggle ${savedOnly?'active':''}" data-action="saved-toggle" aria-pressed="${savedOnly}">${icon('save')} Bewaard</button></div><div class="event-grid">${list.map(e=>eventCard(state,u,e)).join('')||`<div class="empty"><h2>Nog niets hier.</h2><p>${savedOnly?'Bewaar een activiteit om die hier terug te vinden.':'Probeer een andere soort activiteit.'}</p>${button('Toon alle activiteiten','clear-event-filter','','primary')}</div>`}</div>`;}
